using System;
using System.IO;
using System.Text;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Collections.Generic;
namespace Genevo {
sealed class RadarMap : IDisposable {
    Bitmap terrain;public float WorldWidth,WorldHeight;public bool Ready {get{return terrain!=null&&WorldWidth>0&&WorldHeight>0;}}
    public void Dispose(){if(terrain!=null){terrain.Dispose();terrain=null;}}
    public RadarMap(string mod,string raw){try{string asset=ModMetadata.AssetPath(raw);if(String.IsNullOrWhiteSpace(asset)||!Directory.Exists(mod))return;string leaf=asset.Substring(asset.LastIndexOf('/')+1);var map=ModMetadata.Entry(mod,asset+"/"+leaf+".map");if(map==null)return;ReadSize(ModMetadata.MapData(map));byte[] tga=ModMetadata.Entry(mod,asset+"/"+leaf+"_art.tga")??ModMetadata.Entry(mod,asset+"/"+leaf+".tga");if(tga!=null)terrain=DecodeTga(tga);}catch(Exception ex){Program.Log(ex);Dispose();}}
    void ReadSize(byte[] data){using(var r=new BinaryReader(new MemoryStream(data))){if(Encoding.ASCII.GetString(r.ReadBytes(4))!="CkMp")throw new InvalidDataException();int count=r.ReadInt32();if(count<0||count>10000)throw new InvalidDataException();var names=new Dictionary<uint,string>();for(int n=0;n<count;n++){int length=r.ReadByte();string name=Encoding.ASCII.GetString(r.ReadBytes(length));names[r.ReadUInt32()]=name;}while(r.BaseStream.Position+10<=data.Length){uint id=r.ReadUInt32();r.ReadUInt16();int size=r.ReadInt32();long end=r.BaseStream.Position+size;if(size<0||end>data.Length)throw new InvalidDataException();string name;if(names.TryGetValue(id,out name)&&name=="HeightMapData"&&size>=32){uint fullW=r.ReadUInt32(),fullH=r.ReadUInt32(),border=r.ReadUInt32();if(fullW<2*border||fullH<2*border||fullW>10000||fullH>10000)throw new InvalidDataException();WorldWidth=(fullW-2*border)*10;WorldHeight=(fullH-2*border)*10;return;}r.BaseStream.Position=end;}}}
    public static Bitmap DecodeTga(byte[] data){using(var r=new BinaryReader(new MemoryStream(data))){byte id=r.ReadByte(),colorMap=r.ReadByte(),type=r.ReadByte();r.ReadBytes(9);int width=r.ReadUInt16(),height=r.ReadUInt16(),bits=r.ReadByte(),descriptor=r.ReadByte();if(colorMap!=0||(type!=2&&type!=10)||(bits!=24&&bits!=32)||width<1||height<1||width>4096||height>4096)throw new InvalidDataException("Unsupported radar image");r.ReadBytes(id);var bitmap=new Bitmap(width,height);try{int at=0,total=width*height;while(at<total){int count=1;bool repeated=false;if(type==10){byte packet=r.ReadByte();count=(packet&127)+1;repeated=(packet&128)!=0;}Color color=Color.Black;for(int i=0;i<count;i++){if(!repeated||i==0){int b=r.ReadByte(),g=r.ReadByte(),red=r.ReadByte();if(bits==32)r.ReadByte();color=Color.FromArgb(red,g,b);}if(at>=total)throw new InvalidDataException();int x=at%width,y=at/width;if((descriptor&0x20)==0)y=height-1-y;if((descriptor&0x10)!=0)x=width-1-x;bitmap.SetPixel(x,y,color);at++;}}return bitmap;}catch{bitmap.Dispose();throw;}}}
    public void Draw(Graphics g,Rectangle bounds,List<RadarDot> dots){g.InterpolationMode=InterpolationMode.HighQualityBilinear;g.DrawImage(terrain,bounds);if(dots==null)return;var clip=g.Save();g.SetClip(bounds);foreach(var dot in dots){if(dot.X<0||dot.Y<0||dot.X>WorldWidth||dot.Y>WorldHeight)continue;float x=bounds.X+dot.X/WorldWidth*bounds.Width,y=bounds.Bottom-dot.Y/WorldHeight*bounds.Height;using(var brush=new SolidBrush(Color.FromArgb(dot.Color)))g.FillRectangle(brush,x-2,y-2,4,4);}g.Restore(clip);}
}
}
